,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT f.faculty_id,',
'       f.faculty_name,',
'       COUNT(*) AS ta_count,',
'       LISTAGG(s.student_id || '' - '' || s.first_name || '' '' || s.last_name, '', '')',
'           WITHIN GROUP (ORDER BY s.student_id) AS ta_list',
'FROM faculty f',
'JOIN ta_assignment ta ON ta.faculty_id = f.faculty_id',
'JOIN student s ON s.student_id = ta.student_id',
'WHERE ta.assignment_status = ''ACTIVE''',
'GROUP BY f.faculty_id, f.faculty_name',
'HAVING COUNT(*) > 1',
'ORDER BY f.faculty_name;'))
