,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT d.duty_id,',
'       s.first_name || '' '' || s.last_name AS ta_name,',
'       f.faculty_name,',
'       d.task_name, d.description, d.assigned_date, d.deadline, d.status, d.remarks',
'FROM ta_duty d',
'JOIN ta_assignment ta ON ta.assignment_id = d.assignment_id',
'JOIN student s ON s.student_id = ta.student_id',
'JOIN faculty f ON f.faculty_id = ta.faculty_id;'))
