 p_id=>wwv_flow_imp.id(30468194669533915960)
,p_plug_name=>'TA-to- FACULTY MAPPING'
,p_static_id=>'ta-to-faculty-mapping'
,p_region_template_options=>'#DEFAULT#:t-IRR-region--hideHeader js-addHiddenHeadingRoleDesc'
,p_plug_template=>2102002977963900996
,p_plug_display_sequence=>10
,p_plug_item_display_point=>'ABOVE'
,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT s.student_id AS ta_id,',
'       s.first_name || '' '' || s.last_name AS ta_name,',
'       f.faculty_id,',
'       f.faculty_name,',
'       c.course_title,',
'       sec.section_number',
'FROM ta_assignment ta',
'JOIN student s   ON s.student_id  = ta.student_id',
'JOIN faculty f   ON f.faculty_id  = ta.faculty_id',
'JOIN section sec ON sec.section_id = ta.section_id',
'JOIN course c    ON c.course_id   = sec.course_id',
'WHERE ta.assignment_status = ''ACTIVE'';'))
,p_plug_source_type=>'NATIVE_IR'
,p_prn_content_disposition=>'ATTACHMENT'
