,p_query_type=>'SQL'
,p_plug_source=>wwv_flow_string.join(wwv_flow_t_varchar2(
'SELECT',
'    d.department_id,',
'    d.department_name,',
'    s.first_name || '' '' || s.last_name AS ta_name,',
'    s.cgpa',
'FROM department d',
'JOIN student s',
'    ON s.student_id = (',
'        SELECT s2.student_id',
'        FROM student s2',
'        JOIN ta_assignment ta2',
'            ON ta2.student_id = s2.student_id',
'           AND ta2.assignment_status = ''ACTIVE''',
'        WHERE s2.department_id = d.department_id',
'        ORDER BY s2.cgpa DESC',
'        FETCH FIRST 1 ROW ONLY',
'    )',
'ORDER BY d.department_name'))
